-- Block placement states (sql/1031): mc.place_state against what the REAL vanilla 26.3 server produced for the same click (tests/e2e/place_probe.py, compared in full by
-- tests/e2e/compare_place.py: pillar 42 of 42, stairs 56 of 56 ... see docs/GAME.md).  Every row is one recorded placement: the item, the clicked face of the anchor block at
-- (11, -58, 10), the cursor on that face, the player's yaw and pitch, the blocks around, and the state vanilla placed in the target cell (NULL: vanilla placed nothing there).
-- A selection of the recording (the full matrix is the e2e comparison); needs the world-dynamics data (tools/gen_dynamics.sh): without it the file is skipped.
select count(*) > 0 as have_dyn from mc.dyn_state \gset
\if :have_dyn
select mc.generate_flat('minecraft:overworld', x, z) from generate_series(-1, 2) x, generate_series(-1, 2) z;
create temp table pcase (n serial, family text, descr text, item text, face text, yaw real, pitch real, cx float8, cy float8, cz float8, anchor text, setup text, want text);

create or replace function t.place_run(p pcase) returns text language plpgsql as $$
declare s text; d int[]; tx int := 11; ty int := -58; tz int := 10; repl boolean; item_st text; kv text; q text[];
begin
  perform mc.fill('minecraft:overworld', 8, -60, 7, 14, -54, 13, 'minecraft:air');
  perform mc.set_block('minecraft:overworld', 11, -58, 10, p.anchor);
  if p.setup <> '' then
    foreach kv in array string_to_array(p.setup, ';') loop
      q := string_to_array(split_part(kv, '=', 1), ',');
      perform mc.set_block('minecraft:overworld', q[1]::int, q[2]::int, q[3]::int, substring(kv from position('=' in kv) + 1));
    end loop;
  end if;
  repl := mc.place_replaces_clicked(p.anchor, p.item, p.face, p.cy);
  if not repl then tx := 11 + mc.dir_dx(p.face); ty := -58 + mc.dir_dy(p.face); tz := 10 + mc.dir_dz(p.face); end if;
  return mc.place_state('minecraft:overworld', p.item, tx, ty, tz, p.face, 11 + p.cx - tx, -58 + p.cy - ty, 10 + p.cz - tz, repl, p.yaw, p.pitch, false);
end $$;
create or replace function t.norm(s text) returns text language sql immutable as $$     -- the properties in alphabetical order (the registry's order differs per block)
  select case when s like '%[%' then split_part(s, '[', 1) || '[' || (select string_agg(kv, ',' order by kv) from unnest(string_to_array(rtrim(substring(s from '\[(.*)$'), ']'), ',')) kv) || ']' else s end $$;
select t.eq(p.family || ': ' || p.descr, t.norm(coalesce(t.place_run(p), 'NULL')), t.norm(p.want)) from pcase p order by p.n;
\else
\echo SKIP: no world-dynamics data (tools/gen_dynamics.sh): the placement states are not computed without it
\endif
